// Returns the underlying microarchitecture by looking at X86Info's vendor,
// family and model.
@Namespace("cpu_features") public static native @Cast("cpu_features::X86Microarchitecture") int GetX86Microarchitecture(@Const X86Info info);

// Calls cpuid and fills the brand_string.
// - brand_string *must* be of size 49 (beware of array decaying).
// - brand_string will be zero terminated.
@Namespace("cpu_features") public static native @Deprecated void FillX86BrandString(@Cast("char*") BytePointer brand_string);
@Namespace("cpu_features") public static native @Deprecated void FillX86BrandString(@Cast("char*") ByteBuffer brand_string);
@Namespace("cpu_features") public static native @Deprecated void FillX86BrandString(@Cast("char*") byte[] brand_string);

